import Firecrawl from "@mendable/firecrawl-js";
import { env } from "../env";
import { fetchText } from "../sources/util";

/**
 * Reads a VC firm's own website for (a) published email addresses and (b) brand assets.
 * Deterministic: emails are taken verbatim from the page (mailto links, visible text,
 * Cloudflare-obfuscated addresses) — never guessed, never generated by AI.
 */

export type EmailKind = "person" | "pitch" | "general";

export interface FoundEmail {
  email: string;
  kind: EmailKind;
  page: string;
}

export interface BrandAssets {
  domain: string;
  logoUrl: string | null;
  themeColor: string | null;
  page: string;
}

const EXCLUDE =
  /^(privacy|careers?|jobs?|hr|people|recruit|press|media|pr|ir|lp|lps|investor|investors|investorrelations|legal|compliance|grievance|noreply|no-reply|donotreply|support|unsubscribe|abuse|webmaster|admin|accounts?|finance|billing|security|dpo|gdpr|events?|marketing|newsletter)\b/i;
const PITCH = /(pitch|deal|submission|submit|proposal|founders?|startups?|apply|bp|businessplan|plans|newdeals|opportunit|ideas)/i;
const GENERAL = /^(hello|hi|info|contact|connect|team|office|enquir|inquir|mail|general|reachout|talk)/i;

export function rootDomain(urlOrHost: string): string {
  const host = urlOrHost.includes("://") ? new URL(urlOrHost).host : urlOrHost;
  return host.replace(/^www\./, "").toLowerCase();
}

/** Same registrable domain, a subdomain, or the same brand label (accel.com vs accel.in). */
function domainMatches(emailDomain: string, firmDomain: string): boolean {
  const e = emailDomain.toLowerCase();
  const f = firmDomain.toLowerCase();
  if (e === f || e.endsWith(`.${f}`) || f.endsWith(`.${e}`)) return true;
  const label = (d: string) => d.split(".")[0];
  return label(e) === label(f) && label(f).length >= 4;
}

/** Cloudflare "email protection" encodes addresses in data-cfemail hex; decoding is a fixed XOR. */
function decodeCfEmail(hex: string): string | null {
  try {
    const key = parseInt(hex.slice(0, 2), 16);
    let out = "";
    for (let i = 2; i < hex.length; i += 2) out += String.fromCharCode(parseInt(hex.slice(i, i + 2), 16) ^ key);
    return /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(out) ? out : null;
  } catch {
    return null;
  }
}

export function extractEmails(html: string): string[] {
  const found = new Set<string>();
  for (const m of html.matchAll(/mailto:([^"'?>\s\\]+)/gi)) {
    try {
      found.add(decodeURIComponent(m[1]));
    } catch {
      found.add(m[1]);
    }
  }
  for (const m of html.matchAll(/data-cfemail="([0-9a-f]+)"/gi)) {
    const d = decodeCfEmail(m[1]);
    if (d) found.add(d);
  }
  const text = html.replace(/<script[\s\S]*?<\/script>/gi, " ").replace(/<style[\s\S]*?<\/style>/gi, " ");
  for (const m of text.matchAll(/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g)) found.add(m[0]);
  return [...found]
    .map((e) => e.trim().replace(/[\\.,;:)]+$/, "").toLowerCase())
    .filter((e) => !/\.(png|jpe?g|gif|svg|webp|css|js)$/i.test(e) && !/(example|sentry|wixpress|domain)\./i.test(e));
}

export function classifyEmail(email: string, personName: string, firmDomain: string): EmailKind | null {
  const [local, domain] = email.split("@");
  if (!local || !domain || !domainMatches(domain, firmDomain)) return null;
  if (EXCLUDE.test(local)) return null;
  const parts = personName
    .replace(/\([^)]*\)/g, " ")
    .toLowerCase()
    .split(/\s+/)
    .filter((p) => p.length >= 3 && !/^[a-z]\.$/.test(p));
  if (parts.some((p) => local.toLowerCase().includes(p))) return "person";
  if (PITCH.test(local)) return "pitch";
  if (GENERAL.test(local)) return "general";
  return null; // other named people at the firm — not who we're writing to
}

const RANK: Record<EmailKind, number> = { person: 0, pitch: 1, general: 2 };

/** Pick the best published address for this person: their own, else the pitch inbox, else general. */
export function bestEmail(found: FoundEmail[]): FoundEmail | null {
  return [...found].sort((a, b) => RANK[a.kind] - RANK[b.kind])[0] ?? null;
}

const CANDIDATE_PATH = /(contact|pitch|reach|connect|apply|founders|submit|about|team|people)/i;

export function candidateLinks(html: string, base: string): string[] {
  const out = new Set<string>();
  const firm = rootDomain(base);
  for (const m of html.matchAll(/href="([^"#]+)"/gi)) {
    try {
      const u = new URL(m[1], base);
      if (!/^https?:$/.test(u.protocol)) continue;
      if (rootDomain(u.host) !== firm) continue;
      if (CANDIDATE_PATH.test(u.pathname)) out.add(u.origin + u.pathname.replace(/\/$/, ""));
    } catch {
      /* ignore */
    }
  }
  return [...out].slice(0, 4);
}

export function extractBrand(html: string, base: string, firmName = ""): BrandAssets {
  const attr = (tag: string, name: string) => tag.match(new RegExp(`${name}\\s*=\\s*"([^"]*)"`, "i"))?.[1] ?? null;
  const abs = (u: string | null) => {
    if (!u) return null;
    try {
      return new URL(u, base).href;
    } catch {
      return null;
    }
  };

  let themeColor: string | null = null;
  for (const m of html.matchAll(/<meta[^>]+>/gi)) {
    if (/name\s*=\s*"theme-color"/i.test(m[0])) themeColor = attr(m[0], "content");
  }

  // The firm's OWN logo: an <img> that names the firm (alt/src/class) or sits in the site header and
  // is marked "logo". VC homepages are full of portfolio logos, so a bare "logo" match isn't enough.
  // Falls back to apple-touch-icon / the largest non-ICO icon, which always belong to the site.
  const tokens = [
    ...firmName
      .replace(/\([^)]*\)/g, " ")
      .toLowerCase()
      .split(/[^a-z0-9]+/)
      .filter((w) => w.length >= 3 && !["ventures", "venture", "capital", "partners", "fund", "india", "the"].includes(w)),
    rootDomain(base).split(".")[0],
  ];
  const headerEnd = (() => {
    const i = html.search(/<\/header>/i);
    return i > 0 ? i : Math.min(html.length, 6000);
  })();
  let logo: string | null = null;
  let best = 0;
  for (const m of html.matchAll(/<img[^>]+>/gi)) {
    const tag = m[0];
    const src = attr(tag, "src") ?? attr(tag, "data-src");
    if (!src || /^data:image\/gif/i.test(src)) continue;
    const hint = `${attr(tag, "alt") ?? ""} ${attr(tag, "class") ?? ""} ${src}`.toLowerCase();
    const names = tokens.some((t) => hint.includes(t));
    const inHeader = (m.index ?? Infinity) < headerEnd;
    const isLogo = /logo/.test(hint);
    const score = (names ? 3 : 0) + (inHeader && isLogo ? 2 : 0) + (isLogo ? 1 : 0);
    if ((names && isLogo) || (inHeader && isLogo)) {
      if (score > best) {
        best = score;
        logo = abs(src);
      }
    }
  }
  if (!logo) {
    const icons: Array<{ href: string; size: number; apple: boolean }> = [];
    for (const m of html.matchAll(/<link[^>]+>/gi)) {
      const tag = m[0];
      const rel = attr(tag, "rel") ?? "";
      if (!/icon/i.test(rel)) continue;
      const href = attr(tag, "href");
      if (!href) continue;
      const size = Number((attr(tag, "sizes") ?? "0x0").split("x")[0]) || 0;
      icons.push({ href, size, apple: /apple-touch-icon/i.test(rel) });
    }
    icons.sort((a, b) => Number(b.apple) - Number(a.apple) || b.size - a.size);
    const pick = icons.find((i) => !/\.ico(\?|$)/i.test(i.href)) ?? null;
    logo = abs(pick?.href ?? null);
  }

  return { domain: rootDomain(base), logoUrl: logo, themeColor, page: base };
}

/** Fetch a page's HTML directly; fall back to Firecrawl (rendered) when blocked or JS-only. */
export async function getHtml(url: string): Promise<{ html: string; via: "direct" | "firecrawl" } | null> {
  try {
    const html = await fetchText(url, { timeoutMs: 15_000, retries: 1, headers: { Accept: "text/html" } });
    if (html.length > 2_000) return { html, via: "direct" };
  } catch {
    /* fall through */
  }
  if (!env.firecrawlKey) return null;
  try {
    const fc = new Firecrawl({ apiKey: env.firecrawlKey });
    const doc = await fc.scrape(url, { formats: ["rawHtml"], timeout: 30_000 });
    const html = (doc as { rawHtml?: string }).rawHtml ?? "";
    return html ? { html, via: "firecrawl" } : null;
  } catch {
    return null;
  }
}
